import { useCallback, useEffect, useRef, useState } from "react";
import {
  CheckCircle2,
  Download,
  FileText,
  FileUp,
  Loader2,
  Sparkles,
  Trash2,
} from "lucide-react";

import api from "../../services/api";
import { fetchIntakeDocument } from "./SourceDocumentPanel";
import {
  btnPrimarySm,
  tabSelected,
  tabUnselected,
} from "../../utils/buttonStyles";

// Generated by scripts/generate_sample_brd_pdf.py into frontend/public.
const SAMPLE_BRD_URL = `${import.meta.env.BASE_URL}sample-brd-template.pdf`;

function IntakePanel({
  changeRequestId,
  intakeMode,
  setIntakeMode,
  completenessPercent,
  onExtractionApplied,
  setError,
  readOnly = false,
}) {
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [extracting, setExtracting] = useState(false);
  // Set once the current BRD's values are filled into the forms; cleared when
  // a different BRD is uploaded or the BRD is removed.
  const [appliedExtraction, setAppliedExtraction] = useState(null);
  const [brdUpload, setBrdUpload] = useState(null);
  const [loadingBrdStatus, setLoadingBrdStatus] = useState(false);
  const [removingBrd, setRemovingBrd] = useState(false);

  const canExtract =
    Boolean(brdUpload?.uploaded) &&
    Boolean(brdUpload?.upload?.has_text);

  const refreshBrdStatus = useCallback(async () => {
    try {
      setLoadingBrdStatus(true);

      const response = await api.get(
        `/change-requests/${changeRequestId}/intake/brd-status`
      );

      setBrdUpload(response.data);
    } catch {
      setBrdUpload({ uploaded: false, upload: null });
    } finally {
      setLoadingBrdStatus(false);
    }
  }, [changeRequestId]);

  useEffect(() => {
    if (intakeMode === "brd") {
      refreshBrdStatus();
    }
  }, [intakeMode, refreshBrdStatus]);

  const handleUpload = async (event) => {
    const file = event.target.files?.[0];
    if (!file) {
      return;
    }

    try {
      setUploading(true);
      setError("");
      setAppliedExtraction(null);

      const formData = new FormData();
      formData.append("file", file);

      const response = await api.post(
        `/change-requests/${changeRequestId}/intake/upload-brd`,
        formData,
        {
          headers: { "Content-Type": "multipart/form-data" },
        }
      );

      setBrdUpload({
        uploaded: true,
        upload: {
          ...response.data.document,
          has_text: (response.data.character_count || 0) > 0,
          preview: response.data.preview,
          uploaded_at: new Date().toISOString(),
        },
      });
    } catch (err) {
      setError(
        err?.response?.data?.detail || "Failed to upload BRD."
      );
    } finally {
      setUploading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    }
  };

  const handleRemoveBrd = async () => {
    try {
      setRemovingBrd(true);
      setError("");

      await api.delete(`/change-requests/${changeRequestId}/intake/brd`);

      setBrdUpload({ uploaded: false, upload: null });
      setAppliedExtraction(null);
    } catch (err) {
      setError(
        err?.response?.data?.detail || "Failed to remove BRD."
      );
    } finally {
      setRemovingBrd(false);
    }
  };

  const handleExtract = async () => {
    if (!canExtract) {
      setError(
        "Upload a text-based BRD file before extracting fields."
      );
      return;
    }

    try {
      setExtracting(true);
      setError("");

      const response = await api.post(
        `/change-requests/${changeRequestId}/intake/extract-brd`
      );

      // Fill the forms straight away; the user reviews and saves each section.
      const applied = await onExtractionApplied(response.data.merged_preview);
      if (applied) {
        setAppliedExtraction(response.data);
      }
    } catch (err) {
      const detail = err?.response?.data?.detail;
      setError(
        typeof detail === "string"
          ? detail
          : Array.isArray(detail)
          ? detail.map((item) => item.msg || JSON.stringify(item)).join(" ")
          : "Failed to extract BRD. Try a .txt file or check GEMINI_API_KEY."
      );
    } finally {
      setExtracting(false);
    }
  };

  const uploadInfo = brdUpload?.upload;

  return (
    <div className="mb-8 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-sm">
      <div className="border-b border-slate-200 dark:border-slate-700 p-5">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
            <h3 className="font-semibold text-slate-900 dark:text-slate-100">
              Intake method
            </h3>
            <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
              Upload a BRD or enter values manually. Completeness:{" "}
              <span className="font-semibold text-indigo-600 dark:text-indigo-400">
                {completenessPercent ?? 0}%
              </span>
            </p>
          </div>

          <div className="flex rounded-lg border border-slate-200 dark:border-slate-700 p-1">
            <button
              type="button"
              onClick={() => setIntakeMode("brd")}
              className={[
                "rounded-md px-4 py-2 text-sm font-semibold transition",
                intakeMode === "brd" ? tabSelected : tabUnselected,
              ].join(" ")}
            >
              BRD upload
            </button>
            <button
              type="button"
              onClick={() => setIntakeMode("manual")}
              className={[
                "rounded-md px-4 py-2 text-sm font-semibold transition",
                intakeMode === "manual" ? tabSelected : tabUnselected,
              ].join(" ")}
            >
              Manual entry
            </button>
          </div>
        </div>
      </div>

      {intakeMode === "brd" && (
        <div className="space-y-5 p-5">
          <div className="flex flex-wrap items-center gap-3">
            <input
              ref={fileInputRef}
              type="file"
              accept=".pdf,.docx,.txt,.md"
              className="hidden"
              onChange={handleUpload}
            />

            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={readOnly || uploading}
              className="inline-flex items-center gap-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-900 px-4 py-2.5 text-sm font-semibold text-slate-800 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 disabled:opacity-50"
            >
              {uploading ? (
                <Loader2 size={16} className="animate-spin" />
              ) : (
                <FileUp size={16} />
              )}
              {uploading ? "Uploading..." : "Upload BRD"}
            </button>

            <button
              type="button"
              onClick={handleExtract}
              disabled={
                readOnly || extracting || !canExtract || Boolean(appliedExtraction)
              }
              title={
                appliedExtraction
                  ? "Values from this BRD are in the forms. Upload another BRD to extract again."
                  : canExtract
                  ? "Extract intake fields from uploaded BRD"
                  : "Upload a BRD with readable text first"
              }
              className={[
                btnPrimarySm,
                !canExtract || appliedExtraction ? "pointer-events-none" : "",
              ].join(" ")}
            >
              {extracting ? (
                <Loader2 size={16} className="animate-spin" />
              ) : appliedExtraction ? (
                <CheckCircle2 size={16} />
              ) : (
                <Sparkles size={16} />
              )}
              {extracting
                ? "Extracting..."
                : appliedExtraction
                ? "Extracted"
                : "Extract fields"}
            </button>
          </div>

          {loadingBrdStatus && !uploadInfo && (
            <p className="text-sm text-slate-500 dark:text-slate-400">
              Checking for uploaded BRD...
            </p>
          )}

          {uploadInfo && (
            <div
              className={[
                "rounded-lg border p-4",
                uploadInfo.has_text
                  ? "border-green-200 bg-green-50 dark:bg-green-950/40"
                  : "border-amber-200 dark:border-amber-900 bg-amber-50 dark:bg-amber-950/40",
              ].join(" ")}
            >
              <div className="flex items-start gap-3">
                {uploadInfo.has_text ? (
                  <CheckCircle2
                    size={22}
                    className="mt-0.5 shrink-0 text-green-600"
                  />
                ) : (
                  <FileText
                    size={22}
                    className="mt-0.5 shrink-0 text-amber-600"
                  />
                )}

                <div className="min-w-0 flex-1">
                  <p className="text-sm font-semibold text-slate-900 dark:text-slate-100">
                    {uploadInfo.has_text
                      ? "BRD uploaded successfully"
                      : "BRD uploaded but no text detected"}
                  </p>

                  <p className="mt-1 text-sm text-slate-700 dark:text-slate-300">
                    <span className="font-medium">File:</span>{" "}
                    {uploadInfo.filename}
                  </p>

                  <p className="mt-1 text-xs text-slate-600 dark:text-slate-400">
                    {uploadInfo.character_count?.toLocaleString() || 0}{" "}
                    characters
                    {uploadInfo.size_bytes
                      ? ` · ${(uploadInfo.size_bytes / 1024).toFixed(1)} KB`
                      : ""}
                  </p>

                  {!uploadInfo.has_text && (
                    <p className="mt-2 text-xs text-amber-800 dark:text-amber-300">
                      Use a .txt/.md file or a PDF with selectable text.
                      Image-only PDFs cannot be parsed.
                    </p>
                  )}
                </div>

                {uploadInfo.id && uploadInfo.file_available !== false && (
                  <button
                    type="button"
                    onClick={() =>
                      fetchIntakeDocument(changeRequestId, uploadInfo, "download").catch(
                        () => setError("Could not download the BRD.")
                      )
                    }
                    title="Download uploaded BRD"
                    className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-900 px-3 py-2 text-xs font-semibold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800"
                  >
                    <Download size={14} />
                    Download
                  </button>
                )}

                <button
                  type="button"
                  onClick={handleRemoveBrd}
                  disabled={readOnly || removingBrd}
                  title="Detach this BRD from the request (it stays in the request's document history)"
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-red-200 dark:border-red-900 bg-white dark:bg-slate-900 px-3 py-2 text-xs font-semibold text-red-700 dark:text-red-300 hover:bg-red-50 disabled:opacity-50"
                >
                  {removingBrd ? (
                    <Loader2 size={14} className="animate-spin" />
                  ) : (
                    <Trash2 size={14} />
                  )}
                  Remove
                </button>
              </div>
            </div>
          )}

          {!uploadInfo && !loadingBrdStatus && (
            <p className="text-sm text-slate-500 dark:text-slate-400">
              No BRD uploaded yet. Upload a file to enable extraction.
            </p>
          )}

          <div className="flex flex-col items-start gap-3 rounded-lg border border-dashed border-slate-300 bg-slate-50 px-4 py-3 dark:border-slate-600 dark:bg-slate-800/40">
            <p className="text-sm text-slate-600 dark:text-slate-400">
              Don't have a BRD? Download the sample format, replace the
              example values and upload it.
            </p>
            <a
              href={SAMPLE_BRD_URL}
              download="MiniRiskers-sample-BRD.pdf"
              className="inline-flex shrink-0 items-center justify-center gap-2 rounded-lg border border-indigo-200 bg-white px-3 py-2 text-sm font-semibold text-indigo-700 hover:bg-indigo-50 dark:border-indigo-800 dark:bg-slate-900 dark:text-indigo-300 dark:hover:bg-indigo-950/60"
            >
              <Download size={15} />
              Sample BRD (PDF)
            </a>
          </div>
        </div>
      )}
    </div>
  );
}

export default IntakePanel;
